package remotepc

import (
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"os"
	"strings"
	"testing"
)

func TestCipherShippedJavaScriptReference(t *testing.T) {
	// Synthetic known key/IV vector generated by the shipped standalone cipher;
	// it contains no account, device credentials, or captured production traffic.
	raw, err := os.ReadFile("testdata/maodun-reference.json")
	if err != nil {
		t.Fatal(err)
	}
	var vector struct{ Key, IV, Plain, Ciphertext string }
	if err := json.Unmarshal(raw, &vector); err != nil {
		t.Fatal(err)
	}
	c := &Cipher{}
	copy(c.key[:], vector.Key)
	copy(c.iv[:], vector.IV)
	frame, err := base64.RawURLEncoding.DecodeString(vector.Ciphertext)
	if err != nil {
		t.Fatal(err)
	}
	c.header = append([]byte{}, frame[:binary.BigEndian.Uint16(frame[:2])]...)
	plain, err := c.Decrypt(vector.Ciphertext)
	if err != nil || plain != vector.Plain {
		t.Fatalf("reference decrypt failed: %v", err)
	}
	if c.Encrypt(vector.Plain) != vector.Ciphertext {
		t.Fatal("encryption differs from shipped JavaScript")
	}
	for _, encoding := range []*base64.Encoding{base64.StdEncoding, base64.RawStdEncoding, base64.URLEncoding} {
		plain, err := c.Decrypt(encoding.EncodeToString(frame))
		if err != nil || plain != vector.Plain {
			t.Fatalf("server base64 variant failed: %v", err)
		}
	}
}

func TestCipherRoundTripAndMalformedFrames(t *testing.T) {
	c, err := NewCipher()
	if err != nil {
		t.Fatal(err)
	}
	for _, plain := range []string{"", "ok", strings.Repeat("x", 16), "unicode \u2603"} {
		got, err := c.Decrypt(c.Encrypt(plain))
		if err != nil || got != plain {
			t.Fatalf("round trip failed: %v", err)
		}
	}
	frame, _ := base64.RawURLEncoding.DecodeString(c.Encrypt("ok"))
	for name, mutate := range map[string]func([]byte) []byte{
		"short":         func(b []byte) []byte { return b[:12] },
		"magic":         func(b []byte) []byte { b[12]++; return b },
		"header length": func(b []byte) []byte { b[0]++; return b },
		"key length":    func(b []byte) []byte { b[56] = 255; return b },
		"checksum":      func(b []byte) []byte { b[2]++; return b },
		"block length":  func(b []byte) []byte { return b[:len(b)-1] },
		"padding":       func(b []byte) []byte { b[len(b)-1] ^= 255; return b },
	} {
		t.Run(name, func(t *testing.T) {
			bad := mutate(append([]byte{}, frame...))
			if _, err := c.Decrypt(base64.RawURLEncoding.EncodeToString(bad)); err == nil {
				t.Fatal("accepted malformed ciphertext")
			}
		})
	}
}
